add("bullets", chapter="Tu từ: khoa trương 夸张", section="Tu từ 篇章修辞", title="Phép khoa trương (夸张)", size=38,
    items=["Cố ý miêu tả sự vật to hơn hoặc nhỏ hơn thực tế",
           "Tác dụng: làm nổi bật bản chất, đặc điểm của sự vật; khơi gợi trí tưởng tượng phong phú",
           "它能让我们自如地通话、视频、传递消息，哪怕你在天涯海角。",
           "他种的瓜不光甜，几十里外就能闻到瓜香。",
           "看见这鲜绿的麦苗，就闻出白面包子的香味来了。",
           "Hai hướng: phóng đại (扩大) · thu nhỏ (缩小) · Giống thói quen nói quá của tiếng Việt"],
    say=["Phần cuối cùng về lý thuyết là phép tu từ khoa trương, tiếng Trung gọi là 夸张. Tiếng Việt hay gọi là phép nói quá, hay phóng đại.",
         F(0, "Định nghĩa: cố ý miêu tả sự vật khách quan to hơn hoặc nhỏ hơn thực tế, gọi là khoa trương."),
         F(1, "Tác dụng: phép khoa trương giúp làm nổi bật bản chất và đặc điểm của sự vật, đồng thời khơi gợi trí tưởng tượng phong phú của người đọc."),
         F(2, "Ví dụ một, lấy từ bài khóa: 它能让我们自如地通话、视频、传递消息，哪怕你在天涯海角。 Dù bạn ở chân trời góc bể. Tất nhiên không ai ở tận chân trời cả, đây là cách nói quá để nhấn mạnh internet kết nối mọi khoảng cách."),
         F(3, "Ví dụ hai: 他种的瓜不光甜，几十里外就能闻到瓜香。 Dưa anh ấy trồng không chỉ ngọt, mà cách mấy chục dặm cũng ngửi thấy mùi thơm. Mũi người không thể ngửi xa như vậy, đây là phóng đại để nói dưa rất thơm."),
         F(4, "Ví dụ ba: 看见这鲜绿的麦苗，就闻出白面包子的香味来了。 Nhìn thấy những mầm lúa mì xanh tươi này, đã ngửi thấy mùi thơm của bánh bao bột trắng. Lúa mới mọc mầm mà đã nghĩ đến bánh bao, nói quá để thể hiện niềm vui về một mùa bội thu."),
         F(5, "Khoa trương có hai hướng: phóng đại, nói to hơn thực tế; và thu nhỏ, nói nhỏ hơn thực tế. Tiếng Việt cũng có rất nhiều cách nói quá như vậy, ví dụ: nhà chỉ nhỏ bằng bàn tay, hay đói đến mức ăn được cả con voi.")])

add("bullets", section="Tu từ 篇章修辞", title="Luyện tập: câu nào không dùng phép khoa trương?", reveal=True, size=38,
    items=["(1) 我们年轻的时候攒点儿钱多难呐，真是恨不得一分钱掰成两半花。",
           "(2) 密密麻麻的雨点从天空噼里啪啦落了下来。",
           "(3) 阿姨说张大夫医术高明，看见他，病就好了一半。",
           "Đáp án: câu (2) không dùng khoa trương – chỉ miêu tả mưa dày hạt và tiếng mưa rơi.",
           "Câu (1): một đồng bẻ làm đôi để tiêu – phóng đại sự tằn tiện.",
           "Câu (3): vừa thấy bác sĩ đã khỏi một nửa – phóng đại tài của bác sĩ."],
    say=[F(0, "Luyện tập: trong các câu sau, câu nào không dùng phép khoa trương? Câu một: 我们年轻的时候攒点儿钱多难呐，真是恨不得一分钱掰成两半花。 Hồi chúng tôi còn trẻ, dành dụm được chút tiền khó lắm, thật chỉ muốn bẻ một xu làm đôi mà tiêu."),
         F(1, "Câu hai: 密密麻麻的雨点从天空噼里啪啦落了下来。 Những hạt mưa dày đặc lộp độp rơi từ trên trời xuống."),
         F(2, "Câu ba: 阿姨说张大夫医术高明，看见他，病就好了一半。 Dì nói bác sĩ Trương có tay nghề cao, vừa nhìn thấy ông ấy, bệnh đã khỏi một nửa. Các bạn suy nghĩ nhé."),
         F(3, "Đáp án: câu hai không dùng phép khoa trương. 密密麻麻 và 噼里啪啦 chỉ miêu tả hạt mưa dày và âm thanh mưa rơi, không có gì nói quá."),
         F(4, "Câu một có dùng khoa trương: một xu thì không thể bẻ làm đôi, đây là phóng đại để nói sự tằn tiện."),
         F(5, "Câu ba cũng dùng khoa trương: chỉ nhìn thấy bác sĩ thì bệnh không thể khỏi một nửa, đây là cách nói quá để khen tay nghề của bác sĩ.")])

add("bullets", section="Tu từ 篇章修辞", title="Bài tập 4: Khoa trương được dùng như thế nào?", reveal=True, size=36,
    items=["(1) 我住的房间，只有巴掌这么大。",
           "Đáp án: thu nhỏ – căn phòng nhỏ bằng bàn tay, nhấn mạnh phòng rất chật.",
           "(2) 他饿得可以把一头大象吃下去。",
           "Đáp án: phóng đại – ăn được cả con voi, nhấn mạnh rất đói.",
           "(3) 整个礼堂静得连掉根针都能听见。",
           "Đáp án: phóng đại – nghe được cả tiếng kim rơi, nhấn mạnh rất yên tĩnh.",
           "(4) 天热得像下火一样，柏油路都烤化了。",
           "Đáp án: phóng đại – trời như đổ lửa, đường nhựa chảy ra, nhấn mạnh rất nóng."],
    say=[F(0, "Bài tập bốn trong sách: hãy nói xem phép khoa trương được dùng như thế nào trong các câu sau. Câu một: 我住的房间，只有巴掌这么大。 Căn phòng tôi ở chỉ to bằng bàn tay. Các bạn thử phân tích nhé."),
         F(1, "Đáp án: đây là khoa trương theo hướng thu nhỏ. Không phòng nào chỉ bằng bàn tay, người nói cố ý nói nhỏ đi để nhấn mạnh căn phòng rất chật."),
         F(2, "Câu hai: 他饿得可以把一头大象吃下去。 Anh ấy đói đến mức có thể ăn hết cả một con voi."),
         F(3, "Đáp án: khoa trương theo hướng phóng đại, nhấn mạnh anh ấy cực kỳ đói."),
         F(4, "Câu ba: 整个礼堂静得连掉根针都能听见。 Cả hội trường yên tĩnh đến mức kim rơi cũng nghe thấy."),
         F(5, "Đáp án: phóng đại. Tiếng một cây kim rơi rất nhỏ, nghe được cả tiếng đó nghĩa là hội trường cực kỳ yên lặng. Tiếng Việt cũng nói: im phăng phắc, nghe được cả tiếng kim rơi."),
         F(6, "Câu bốn: 天热得像下火一样，柏油路都烤化了。 Trời nóng như đổ lửa, đường nhựa cũng bị nướng chảy ra."),
         F(7, "Đáp án: phóng đại, nhấn mạnh trời cực kỳ nóng. Các bạn thấy đấy, mẫu câu tính từ cộng 得 cộng một hậu quả nói quá là cách dùng khoa trương rất phổ biến trong tiếng Trung.")])

